CREATE TYPE "Role" AS ENUM ('CUSTOMER','WAREHOUSE','SUPPORT','ADMIN','SUPERADMIN');
CREATE TYPE "ProductStatus" AS ENUM ('DRAFT','ACTIVE','INACTIVE','ARCHIVED');
CREATE TYPE "FuelType" AS ENUM ('PETROL','DIESEL','HYBRID','PHEV','ELECTRIC','LPG','OTHER');
CREATE TYPE "OrderStatus" AS ENUM ('DRAFT','AWAITING_PAYMENT','PAID','PROCESSING','AWAITING_STOCK','PICKING','PACKED','HANDED_TO_COURIER','READY_FOR_PICKUP','COMPLETED','CANCELLED','RETURN_IN_PROGRESS','PARTIALLY_REFUNDED','REFUNDED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','AUTHORIZED','PAID','FAILED','REFUNDED','PARTIAL_REFUND');
CREATE TYPE "ShippingStatus" AS ENUM ('PENDING','PREPARING','SHIPPED','READY','DELIVERED','RETURNED');
CREATE TYPE "InventoryMovementType" AS ENUM ('RECEIPT','SALE','RESERVATION','RELEASE','RETURN','SCRAP','ADJUSTMENT','TRANSFER_IN','TRANSFER_OUT');
CREATE TYPE "PromotionType" AS ENUM ('PERCENT','FIXED','FREE_SHIPPING');
CREATE TYPE "PromotionScope" AS ENUM ('PRODUCT','CATEGORY','MANUFACTURER','CART');
CREATE TYPE "ReturnStatus" AS ENUM ('REQUESTED','APPROVED','REJECTED','RECEIVED','REFUNDED');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"emailVerifiedAt" TIMESTAMP(3),"refreshTokenHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Address" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"label" TEXT NOT NULL,"recipient" TEXT NOT NULL,"postalCode" TEXT NOT NULL,"city" TEXT NOT NULL,"street" TEXT NOT NULL,"country" TEXT NOT NULL DEFAULT 'HU',"phone" TEXT,"isBilling" BOOLEAN NOT NULL DEFAULT false,"isDefault" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "VehicleBrand" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL); CREATE UNIQUE INDEX "VehicleBrand_name_key" ON "VehicleBrand"("name");
CREATE TABLE "VehicleModel" ("id" TEXT PRIMARY KEY,"brandId" TEXT NOT NULL,"name" TEXT NOT NULL); CREATE UNIQUE INDEX "VehicleModel_brandId_name_key" ON "VehicleModel"("brandId","name");
CREATE TABLE "VehicleGeneration" ("id" TEXT PRIMARY KEY,"modelId" TEXT NOT NULL,"name" TEXT NOT NULL,"yearFrom" INTEGER NOT NULL,"yearTo" INTEGER,"bodyStyle" TEXT NOT NULL);
