CREATE TABLE "Manufacturer" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL); CREATE UNIQUE INDEX "Manufacturer_name_key" ON "Manufacturer"("name");
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"parentId" TEXT,"name" TEXT NOT NULL,"slug" TEXT NOT NULL); CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"sku" TEXT NOT NULL,"ean" TEXT,"shortDescription" TEXT NOT NULL,"description" TEXT NOT NULL,"manufacturerId" TEXT NOT NULL,"netPrice" DECIMAL(12,2) NOT NULL,"grossPrice" DECIMAL(12,2) NOT NULL,"vatRate" DECIMAL(5,2) NOT NULL,"purchasePrice" DECIMAL(12,2),"weightGrams" INTEGER,"warrantyMonths" INTEGER DEFAULT 24,"status" "ProductStatus" NOT NULL DEFAULT 'DRAFT',"seoTitle" TEXT,"seoDescription" TEXT,"minStock" INTEGER NOT NULL DEFAULT 2,"universal" BOOLEAN NOT NULL DEFAULT false,"specs" JSONB,"oemNumbers" TEXT[] NOT NULL,"alternativeNumbers" TEXT[] NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug"); CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku");
CREATE TABLE "ProductImage" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"url" TEXT NOT NULL,"alt" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"isPrimary" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "ProductFitment" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"engineId" TEXT NOT NULL,"notes" TEXT,"exclusions" TEXT); CREATE UNIQUE INDEX "ProductFitment_productId_engineId_key" ON "ProductFitment"("productId","engineId");
CREATE TABLE "ProductRelation" ("id" TEXT PRIMARY KEY,"fromProductId" TEXT NOT NULL,"toProductId" TEXT NOT NULL,"kind" TEXT NOT NULL); CREATE UNIQUE INDEX "ProductRelation_fromProductId_toProductId_kind_key" ON "ProductRelation"("fromProductId","toProductId","kind");
CREATE TABLE "Warehouse" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"address" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true); CREATE UNIQUE INDEX "Warehouse_code_key" ON "Warehouse"("code");
CREATE TABLE "InventoryBalance" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"physical" INTEGER NOT NULL DEFAULT 0,"reserved" INTEGER NOT NULL DEFAULT 0,"damaged" INTEGER NOT NULL DEFAULT 0,"incoming" INTEGER NOT NULL DEFAULT 0); CREATE UNIQUE INDEX "InventoryBalance_productId_warehouseId_key" ON "InventoryBalance"("productId","warehouseId");
CREATE TABLE "InventoryMovement" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"type" "InventoryMovementType" NOT NULL,"quantity" INTEGER NOT NULL,"previousPhysical" INTEGER NOT NULL,"newPhysical" INTEGER NOT NULL,"previousReserved" INTEGER NOT NULL,"newReserved" INTEGER NOT NULL,"orderId" TEXT,"actorId" TEXT,"reason" TEXT,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "InventoryMovement_productId_warehouseId_createdAt_idx" ON "InventoryMovement"("productId","warehouseId","createdAt");
CREATE TABLE "Cart" ("id" TEXT PRIMARY KEY,"userId" TEXT,"sessionKey" TEXT,"couponCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "Cart_sessionKey_idx" ON "Cart"("sessionKey");
