CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"orderNumber" TEXT NOT NULL,"userId" TEXT,"email" TEXT NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'AWAITING_PAYMENT',"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"shippingStatus" "ShippingStatus" NOT NULL DEFAULT 'PENDING',"subtotalGross" DECIMAL(12,2) NOT NULL,"discountGross" DECIMAL(12,2) NOT NULL DEFAULT 0,"shippingGross" DECIMAL(12,2) NOT NULL DEFAULT 0,"totalGross" DECIMAL(12,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'HUF',"paymentMethod" TEXT NOT NULL,"shippingMethod" TEXT NOT NULL,"shippingAddress" JSONB NOT NULL,"billingAddress" JSONB NOT NULL,"trackingNumber" TEXT,"internalNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber");
CREATE TABLE "OrderItem" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"productId" TEXT,"sku" TEXT NOT NULL,"productName" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitNet" DECIMAL(12,2) NOT NULL,"vatRate" DECIMAL(5,2) NOT NULL,"unitGross" DECIMAL(12,2) NOT NULL,"discountGross" DECIMAL(12,2) NOT NULL DEFAULT 0,"lineGross" DECIMAL(12,2) NOT NULL);
